            }
            if (type == typeof(string))
            {
                return Create_String(options);
            }
            if (type == typeof(uint))
            {
                return Create_UInt32(options);
            }
            if (type == typeof(uint?))
            {
                return Create_NullableUInt32(options);
            }
            if (type == typeof(ulong))
            {
                return Create_UInt64(options);
            }
            if (type == typeof(ulong?))
            {
                return Create_NullableUInt64(options);
            }
            return null;
        }
    }
}
